const CAPACIDAD_HOTEL = 75;
const ESTADOS_VALIDOS = ["Confirmada", "No Show"];

function parseDate(str) {
  const d = new Date(str);
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
}
function addDays(date, n) {
  const d = new Date(date);
  d.setUTCDate(d.getUTCDate() + n);
  return d;
}
function toISODate(date) { return date.toISOString().slice(0, 10); }
function lunesDeLaSemana(date) {
  const d = new Date(date);
  const dia = (d.getUTCDay() + 6) % 7;
  return addDays(d, -dia);
}

const registros = $('Extract from File').all();

const reservas = registros
  .map((item, index) => {
    const f = item.json;
    return {
      id: index,
      checkIn: parseDate(f.CheckIn),
      checkOut: f.CheckOut ? parseDate(f.CheckOut) : null,
      fechaReserva: parseDate(f.FechaReserva),
      adr: Number(f.ADR) || 0,
      estado: f.Estado
    };
  })
  .filter(r => ESTADOS_VALIDOS.includes(r.estado));

const historico = {};
reservas.forEach(r => {
  if (!r.checkOut) return;
  let actual = new Date(r.checkIn);
  while (actual < r.checkOut) {
    const key = toISODate(actual);
    if (!historico[key]) historico[key] = { habitacionesSet: new Set(), adrSum: 0, count: 0 };
    historico[key].habitacionesSet.add(r.id);
    historico[key].adrSum += r.adr;
    historico[key].count += 1;
    actual = addDays(actual, 1);
  }
});

const semanas = {};
Object.keys(historico).forEach(fechaKey => {
  const fecha = parseDate(fechaKey);
  const lunes = toISODate(lunesDeLaSemana(fecha));
  if (!semanas[lunes]) semanas[lunes] = { dias: [] };
  semanas[lunes].dias.push({ fecha: fechaKey, ...historico[fechaKey] });
});

function pickupSemana(lunesStr, dias) {
  const lunes = parseDate(lunesStr);
  const corte = addDays(lunes, -7);
  const idsEnSemana = new Set();
  reservas.forEach(r => {
    if (!r.checkOut) return;
    const solapa = r.checkIn < addDays(lunes, 7) && r.checkOut > lunes;
    if (solapa && r.fechaReserva <= corte) idsEnSemana.add(r.id);
  });
  return idsEnSemana.size;
}

const resultado = Object.entries(semanas).map(([lunes, data]) => {
  const dias = data.dias;
  const ocupaciones = dias.map(d => (d.habitacionesSet.size / CAPACIDAD_HOTEL) * 100);
  const adrs = dias.map(d => d.count ? d.adrSum / d.count : 0);
  const media = arr => arr.length ? arr.reduce((a,b)=>a+b,0) / arr.length : 0;

  const ocupacion_media = Number(media(ocupaciones).toFixed(2));
  const adr = Number(media(adrs).toFixed(2));
  const revpar = Number(((ocupacion_media / 100) * adr).toFixed(2));

  return {
    json: {
      fecha_inicio: lunes,
      fecha_fin: toISODate(addDays(parseDate(lunes), 6)),
      ocupacion_media,
      adr,
      revpar,
      pickup_7: pickupSemana(lunes, dias),
      dias_con_datos: dias.length
    }
  };
});

return resultado;

