  2025: ["2025-01-01","2025-01-06","2025-04-17","2025-04-18","2025-05-01","2025-07-25","2025-08-15","2025-10-12","2025-11-01","2025-12-06","2025-12-08","2025-12-25"]
};

function esVacacionesEscolares(fechaISO) {
  return VACACIONES_ESCOLARES_GALICIA.some(p => fechaISO >= p.inicio && fechaISO <= p.fin);
}
function esFestivo(fechaISO) {
  const anio = Number(fechaISO.slice(0, 4));
  return (FESTIVOS_POR_ANIO[anio] || []).includes(fechaISO);
}

return items.map(item => {
  const { fecha_inicio, fecha_fin } = item.json;
  const dias = [];
  let cursor = new Date(fecha_inicio);
  const fin = new Date(fecha_fin);
  while (cursor <= fin) {
    dias.push(toISODate(cursor));
    cursor = addDays(cursor, 1);
  }

  const dias_vacaciones = dias.filter(esVacacionesEscolares).length;
  const dias_festivos = dias.filter(esFestivo).length;

  return {
    json: {
