      dias_vacaciones_escolares: dias_vacaciones,
      dias_festivos: dias_festivos,
      pct_dias_vacaciones: Number((dias_vacaciones / dias.length).toFixed(2)),
      pct_dias_festivos: Number((dias_festivos / dias.length).toFixed(2))
    }
  };
});

const climaData = $('Obtener Clima Historico (1 llamada)').first().json.daily;
const climaPorFecha = {};

if (climaData && climaData.time) {
  climaData.time.forEach((fecha, i) => {
    climaPorFecha[fecha] = {
      temp_max: climaData.temperature_2m_max?.[i] ?? null,
      temp_min: climaData.temperature_2m_min?.[i] ?? null,
      precipitacion: climaData.precipitation_sum?.[i] ?? null
    };
  });
}

function toISODate(date) { return date.toISOString().slice(0, 10); }
function addDays(date, n) {
  const d = new Date(date);
  d.setUTCDate(d.getUTCDate() + n);
  return d;
}

return items.map(item => {
  const { fecha_inicio, fecha_fin } = item.json;
  const dias = [];
  let cursor = new Date(fecha_inicio);
  const fin = new Date(fecha_fin);
  while (cursor <= fin) {
    dias.push(toISODate(cursor));
    cursor = addDays(cursor, 1);
  }

  const registrosClima = dias.map(f => climaPorFecha[f]).filter(Boolean);
  const diasConLluvia = registrosClima.filter(c => c.precipitacion !== null && c.precipitacion >= 1).length;
  const diasBuenTiempo = registrosClima.filter(c => c.precipitacion !== null && c.precipitacion < 1 && c.temp_max > 20).length;

  const media = arr => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null;
  const tempMaxMedia = media(registrosClima.map(c => c.temp_max).filter(v => v !== null));
  const precipTotal = registrosClima.reduce((s, c) => s + (c.precipitacion ?? 0), 0);

  return {
    json: {
      ...item.json,
      dias_con_datos_clima: registrosClima.length,
      pct_dias_lluvia: registrosClima.length ? Number((diasConLluvia / registrosClima.length).toFixed(2)) : null,
      pct_dias_buen_tiempo: registrosClima.length ? Number((diasBuenTiempo / registrosClima.length).toFixed(2)) : null,
      temp_max_media: tempMaxMedia !== null ? Number(tempMaxMedia.toFixed(1)) : null,
      precipitacion_total_mm: Number(precipTotal.toFixed(1))
    }
  };
});
